+        <KanbanColumn Title="In Progress"
+                      Tasks="InProgressTasks"
+                      ShowMoveLeft="true"
+                      ShowMoveRight="true"
+                      OnMoveLeft="id => MoveTask(id, \"To Do\")"
+                      OnMoveRight="id => MoveTask(id, \"Done\")"
+                      OnTaskCreated="data => CreateTask(data, \"In Progress\")" />
+
+        <KanbanColumn Title="Done"
+                      Tasks="DoneTasks"
+                      ShowMoveLeft="true"
+                      ShowMoveRight="false"
+                      OnMoveLeft="id => MoveTask(id, \"In Progress\")"
+                      OnTaskCreated="data => CreateTask(data, \"Done\")" />
+    </div>
+}
+
+@code {
+    private List<TaskItem> allTasks = new();
+    private List<TaskItem> filteredTasks = new();
+    private string searchTerm = "";
+    private bool isLoading = true;
+    private string? errorMessage;
+
+    private List<TaskItem> TodoTasks => filteredTasks.Where(t => t.Status == "To Do").ToList();
+    private List<TaskItem> InProgressTasks => filteredTasks.Where(t => t.Status == "In Progress").ToList();
+    private List<TaskItem> DoneTasks => filteredTasks.Where(t => t.Status == "Done").ToList();
+
+    protected override async Task OnInitializedAsync()
+    {
+        await LoadTasks();
+    }
+
+    private async Task LoadTasks()
+    {
+        try
+        {
+            isLoading = true;
+            errorMessage = null;
+            allTasks = await TaskService.GetAllTasksAsync();
+            ApplyFilter();
+        }
+        catch (Exception ex)
+        {
+            errorMessage = ex.Message;
+        }
+        finally
+        {
+            isLoading = false;
+        }
+    }
+
+    private void HandleSearch(string term)
+    {
+        searchTerm = term;
+        ApplyFilter();
+    }
+
+    private void ApplyFilter()
+    {
+        filteredTasks = string.IsNullOrWhiteSpace(searchTerm)
+            ? allTasks.ToList()
+            : allTasks.Where(t => t.Title.Contains(searchTerm, StringComparison.OrdinalIgnoreCase)).ToList();
+    }
+
+    private async Task MoveTask(int taskId, string newStatus)
+    {
+        try
+        {
+            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
+            var task = allTasks.FirstOrDefault(t => t.Id == taskId);
+            if (task is not null)
+            {
+                allTasks = allTasks.Select(t => t.Id == taskId ? t with { Status = newStatus } : t).ToList();
+                ApplyFilter();
+            }
+        }
+        catch (Exception ex)
+        {
+            errorMessage = ex.Message;
+        }
+    }
+
+    private async Task CreateTask((string Title, string Assignee, string Priority, DateTime DueDate) data, string status)
+    {
+        try
+        {
+            var newTask = await TaskService.CreateTaskAsync(data.Title, data.Assignee, data.Priority, data.DueDate);
+            allTasks.Add(newTask with { Status = status });
+            ApplyFilter();
+        }
+        catch (Exception ex)
+        {
+            errorMessage = ex.Message;
+        }
+    }
+}
